// Test-only receiver process. It accepts private configuration through stdin, never argv/logs.
import{createServer}from'node:http';import pg from'pg';import{acceptWebhookEvent}from'../../examples/webhook-consumer/consumer';
if(process.env.LOCAL_DEVELOPMENT!=='true'||process.env.NODE_ENV!=='test')throw new Error('Owned fixture mode required');
let input='';for await(const part of process.stdin){input+=part.toString();if(Buffer.byteLength(input)>8192)throw new Error('Fixture configuration too large');}
const config=JSON.parse(input)as{connection_string:string;schema:string;workspace:string;consumer:string;secret:string;hold_ack:boolean};
if(Object.keys(config).sort().join(',')!=='connection_string,consumer,hold_ack,schema,secret,workspace'||!/^hook_restart_[a-f0-9]{32}$/.test(config.schema)||![config.workspace,config.consumer].every((id)=>/^[a-f0-9-]{36}$/.test(id))||!/^[a-f0-9]{64}$/.test(config.secret)||typeof config.hold_ack!=='boolean'||!['localhost','127.0.0.1','postgres'].includes(new URL(config.connection_string).hostname))throw new Error('Invalid owned fixture configuration');
const pool=new pg.Pool({connectionString:config.connection_string,max:2});
const server=createServer(async(req,res)=>{let tx:pg.PoolClient|undefined;try{if(req.method!=='POST'||req.url!=='/')throw new Error('Invalid fixture request');const chunks:Buffer[]=[];let size=0;for await(const part of req){size+=part.length;if(size>65536)throw new Error('Fixture body too large');chunks.push(Buffer.from(part));}const body=Buffer.concat(chunks);tx=await pool.connect();await tx.query('BEGIN');await tx.query('SET LOCAL search_path TO '+config.schema+',pg_catalog');const result=await acceptWebhookEvent(tx,config.consumer,config.workspace,body,new Headers(Object.entries(req.headers).map(([k,v]):[string,string]=>[k,String(v)])),[{secret_version:1,valid_until:null,secret:config.secret}]);await tx.query('COMMIT');process.stdout.write(JSON.stringify({event:'committed'})+'\n');if(config.hold_ack)return;res.writeHead(204,{'X-Fixture-Duplicate':String(result.duplicate)});res.end();}catch{if(tx)await tx.query('ROLLBACK').catch(()=>{});res.writeHead(400);res.end();}finally{tx?.release();}});
server.on('error',()=>{process.stderr.write('Owned receiver fixture failed\n');process.exitCode=1;});server.listen(0,'127.0.0.1',()=>{const address=server.address();if(!address||typeof address==='string')throw new Error('Invalid fixture address');process.stdout.write(JSON.stringify({event:'ready',pid:process.pid,port:address.port})+'\n');});
process.on('SIGTERM',()=>{server.closeAllConnections();server.close(()=>{void pool.end().then(()=>process.exit(0));});});
